selector_to_html = {"a[href=\"#submodules\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Submodules<a class=\"headerlink\" href=\"#submodules\" title=\"Link to this heading\">\u00b6</a></h2>", "a[href=\"coupled_solver/index.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">pyskyfire.regen.coupled_solver<a class=\"headerlink\" href=\"#module-pyskyfire.regen.coupled_solver\" title=\"Link to this heading\">\u00b6</a></h1><p>Coupled film + regenerative cooling solver.</p><p>The hot-side boundary condition can come from either the hot combustion gas,\na film cooling solution, or a mix of the two along the chamber.</p>", "a[href=\"design_inputs/index.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">pyskyfire.regen.design_inputs<a class=\"headerlink\" href=\"#module-pyskyfire.regen.design_inputs\" title=\"Link to this heading\">\u00b6</a></h1><p>Keyword-dispatched design inputs for cooling-channel geometry.</p><p>Most user-facing geometry inputs in <a class=\"reference internal\" href=\"index.html#module-pyskyfire.regen\" title=\"pyskyfire.regen\"><code class=\"xref py py-mod docutils literal notranslate\"><span class=\"pre\">pyskyfire.regen</span></code></a> accept either a\nconstant or a function of position.  Historically every such function had to\ntake exactly one positional argument <code class=\"docutils literal notranslate\"><span class=\"pre\">x</span></code>, even when the value did not depend\non it.  This module replaces that convention: a design-input function declares\nthe quantities it needs <em>by parameter name</em>, and only those are supplied.</p>", "a[href=\"film_solver/index.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">pyskyfire.regen.film_solver<a class=\"headerlink\" href=\"#module-pyskyfire.regen.film_solver\" title=\"Link to this heading\">\u00b6</a></h1><h2>Attributes<a class=\"headerlink\" href=\"#attributes\" title=\"Link to this heading\">\u00b6</a></h2>", "a[href=\"#module-pyskyfire.regen\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">pyskyfire.regen<a class=\"headerlink\" href=\"#module-pyskyfire.regen\" title=\"Link to this heading\">\u00b6</a></h1><h2>Submodules<a class=\"headerlink\" href=\"#submodules\" title=\"Link to this heading\">\u00b6</a></h2>", "a[href=\"channel_layout/index.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">pyskyfire.regen.channel_layout<a class=\"headerlink\" href=\"#module-pyskyfire.regen.channel_layout\" title=\"Link to this heading\">\u00b6</a></h1><p>Resolve nominal cooling circuits into patternable channel layouts.</p><p>The analytical resolver only applies constant angular phase shifts, so every\nseed remains an exact copy of its circuit\u2019s nominal reference path.  The\nnumerical resolver retains the visualization packing solver and may deform the\nangular coordinate along a seed.</p>", "a[href=\"thrust_chamber/index.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">pyskyfire.regen.thrust_chamber<a class=\"headerlink\" href=\"#module-pyskyfire.regen.thrust_chamber\" title=\"Link to this heading\">\u00b6</a></h1><h2>Classes<a class=\"headerlink\" href=\"#classes\" title=\"Link to this heading\">\u00b6</a></h2>", "a[href=\"channel_placement/index.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">pyskyfire.regen.channel_placement<a class=\"headerlink\" href=\"#module-pyskyfire.regen.channel_placement\" title=\"Link to this heading\">\u00b6</a></h1><h2>Classes<a class=\"headerlink\" href=\"#classes\" title=\"Link to this heading\">\u00b6</a></h2>", "a[href=\"outer_wall/index.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">pyskyfire.regen.outer_wall<a class=\"headerlink\" href=\"#module-pyskyfire.regen.outer_wall\" title=\"Link to this heading\">\u00b6</a></h1><p>The cold-side envelope of a cooling circuit, read like a contour.</p><p><a class=\"reference internal\" href=\"contour/Contour.html#pyskyfire.regen.contour.Contour\" title=\"pyskyfire.regen.contour.Contour\"><code class=\"xref py py-class docutils literal notranslate\"><span class=\"pre\">Contour</span></code></a> describes where the hot gas sees the\nchamber. This describes the other face of the same hardware: the outermost\nsurface the cooling channels and their walls reach. It is what a manifold\nwrapped around the chamber has to sit against, and it is stated the same way \u2013\na radius as a function of axial station, plus the direction the wall faces\nthere \u2013 so the two can be read side by side.</p>", "a[href=\"cad_geometry/index.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">pyskyfire.regen.cad_geometry<a class=\"headerlink\" href=\"#module-pyskyfire.regen.cad_geometry\" title=\"Link to this heading\">\u00b6</a></h1><p>Geometry-only transverse sections and hot-wall surfaces.</p><p>No solver dimensions, paths or section analytics are modified here. Oblique\nsections represent the local prismatic approximation, not exact CAD sweep cuts.</p>", "a[href=\"channel_height/index.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">pyskyfire.regen.channel_height<a class=\"headerlink\" href=\"#module-pyskyfire.regen.channel_height\" title=\"Link to this heading\">\u00b6</a></h1><h2>Functions<a class=\"headerlink\" href=\"#functions\" title=\"Link to this heading\">\u00b6</a></h2>", "a[href=\"contour/index.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">pyskyfire.regen.contour<a class=\"headerlink\" href=\"#module-pyskyfire.regen.contour\" title=\"Link to this heading\">\u00b6</a></h1><p>contour.py</p><p>Functinos and methods that together create a thrust chamber contour (combustion chamber + nozzle).</p>", "a[href=\"cross_section/index.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">pyskyfire.regen.cross_section<a class=\"headerlink\" href=\"#module-pyskyfire.regen.cross_section\" title=\"Link to this heading\">\u00b6</a></h1><h2>Classes<a class=\"headerlink\" href=\"#classes\" title=\"Link to this heading\">\u00b6</a></h2>", "a[href=\"channel_helpers/index.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">pyskyfire.regen.channel_helpers<a class=\"headerlink\" href=\"#module-pyskyfire.regen.channel_helpers\" title=\"Link to this heading\">\u00b6</a></h1><p>Shared geometric helpers for regenerative cooling-channel paths.</p><p>The regenerative model stores paths in cylindrical coordinates as\n<code class=\"docutils literal notranslate\"><span class=\"pre\">[axial_position,</span> <span class=\"pre\">radius,</span> <span class=\"pre\">angle]</span></code>.  This module turns those lightweight\narrays into Cartesian section planes only when a consumer needs them.  The\npath a consumer passes in decides what the planes mean: CAD sections and\nvisualization frame themselves on the cross-section base point, not on the\ncoolant centroid.</p>", "a[href=\"channel_construction/index.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">pyskyfire.regen.channel_construction<a class=\"headerlink\" href=\"#module-pyskyfire.regen.channel_construction\" title=\"Link to this heading\">\u00b6</a></h1><p>Resolve nominal paths into physical section anchors, arcs and centroids.</p><p>The normal section is projected locally onto an engine-axis-normal plane to\nallocate gas area. This is exact for prismatic sections; a curved CAD loft is\nan approximation to the sequence of these local sections.</p>", "a[href=\"coolant_properties/index.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">pyskyfire.regen.coolant_properties<a class=\"headerlink\" href=\"#module-pyskyfire.regen.coolant_properties\" title=\"Link to this heading\">\u00b6</a></h1><p>Coolant film properties and two-phase modelling limits for the regenerative march.</p>"}
skip_classes = ["headerlink", "sd-stretched-link"]

window.onload = function () {
    for (const [select, tip_html] of Object.entries(selector_to_html)) {
        const links = document.querySelectorAll(` ${select}`);
        for (const link of links) {
            if (skip_classes.some(c => link.classList.contains(c))) {
                continue;
            }

            tippy(link, {
                content: tip_html,
                allowHTML: true,
                arrow: true,
                placement: 'auto-start', maxWidth: 600, interactive: false,
                onShow(instance) {MathJax.typesetPromise([instance.popper]).then(() => {});},
            });
        };
    };
    console.log("tippy tips loaded!");
};
